class ListRepo:
    def __init__(self):
        self.items = []

    def add(self, item):
        self.items.append(item)

    def all(self):
        return list(self.items)


class FinanceService:
    def __init__(self, repo):
        self.repo = repo

    def add(self, kind, amount):
        if kind not in ("income", "expense"):
            raise ValueError("неизвестный тип")
        if amount <= 0:
            raise ValueError("сумма должна быть положительной")
        self.repo.add((kind, amount))

    def balance(self):
        return sum(a if k == "income" else -a for k, a in self.repo.all())


service = FinanceService(ListRepo())
for kind, amount in [("income", 100), ("expense", 30), ("gift", 10), ("expense", 0), ("expense", 20)]:
    try:
        service.add(kind, amount)
    except ValueError as e:
        print("ошибка:", e)
print(service.balance())
